// Age alone does not tell you whether money is coming in. A formally disputed
// invoice is not 92% collectable because it happens to be young, and an invoice
// whose payment promise was already broken is worth less than a quiet one of the
// same age. Both are scored down here, and both adjustments are itemised so the
// finance lead can see exactly which invoice moved the headline number.
const COLLECT_ODDS = { current: 0.98, '1-30': 0.92, '31-60': 0.75, '61-90': 0.55, '90+': 0.3, unknown: 0.5 };
const DISPUTED_ODDS_CAP = 0.35;
const BROKEN_PROMISE_FACTOR = 0.6;
const MINUTES_PER_MANUAL_CHASE = 9;

const invoices = $('Assess Every Invoice').all().map(function (i) { return i.json; });
const customers = $('One Message per Customer').all().map(function (i) { return i.json; });

function sum(list, field) {
  return list.reduce(function (s, r) { return s + (Number(r[field]) || 0); }, 0);
}
function splitNumbers(s) {
  return String(s || '').split(',').map(function (x) { return x.trim(); }).filter(function (x) { return x.length > 0; });
}
function baseOdds(r) {
  const b = r.aging_bucket || 'unknown';
  return COLLECT_ODDS[b] === undefined ? 0.5 : COLLECT_ODDS[b];
}
// The report is only allowed to claim an account manager was pinged if there is a
// wire from that customer's branch to the Slack node. Escalations go straight there;
// reminders only reach it through the manager-worthy filter.
function reachesSlack(c) {
  if (c.route === 'escalate') return true;
  return c.route === 'reminder' && c.notify_manager === true;
}

const live = invoices.filter(function (r) { return (Number(r.outstanding) || 0) > 0; });

// Score every invoice on its own before rolling it into a bucket.
const adjustments = [];
const scored = live.map(function (r) {
  const base = baseOdds(r);
  let odds = base;
  const why = [];
  if (r.outcome === 'disputed') {
    if (DISPUTED_ODDS_CAP < odds) odds = DISPUTED_ODDS_CAP;
    why.push('formally disputed');
  }
  if (r.broken_promise) {
    odds = odds * BROKEN_PROMISE_FACTOR;
    why.push('payment promise already broken');
  }
  const outstanding = Number(r.outstanding) || 0;
  const row = {
    invoice_number: r.invoice_number,
    customer_id: r.customer_id,
    customer_name: r.customer_name,
    aging_bucket: r.aging_bucket,
    outstanding: outstanding,
    base_odds: base,
    odds: odds,
    base_expected: outstanding * base,
    expected: outstanding * odds,
    reason: why.join(' and ')
  };
  if (odds !== base) {
    adjustments.push({
      invoice: r.invoice_number,
      customer: r.customer_name,
      bucket: r.aging_bucket,
      outstanding: outstanding,
      odds_before: base,
      odds_after: Math.round(odds * 1000) / 1000,
      expected_before: Math.round(outstanding * base),
      expected_after: Math.round(outstanding * odds),
      reduction: Math.round(outstanding * base) - Math.round(outstanding * odds),
      reason: why.join(' and ')
    });
  }
  return row;
});

const buckets = {};
for (const r of scored) {
  const b = r.aging_bucket || 'unknown';
  if (!buckets[b]) buckets[b] = { bucket: b, count: 0, value: 0, expected: 0, base_expected: 0 };
  buckets[b].count = buckets[b].count + 1;
  buckets[b].value = buckets[b].value + r.outstanding;
  buckets[b].expected = buckets[b].expected + r.expected;
  buckets[b].base_expected = buckets[b].base_expected + r.base_expected;
}
const order = ['current', '1-30', '31-60', '61-90', '90+', 'unknown'];
const aging = order.filter(function (b) { return buckets[b]; }).map(function (b) {
  return {
    bucket: buckets[b].bucket,
    count: buckets[b].count,
    value: buckets[b].value,
    expected_cash: Math.round(buckets[b].expected),
    expected_cash_before_risk: Math.round(buckets[b].base_expected),
    risk_discount: Math.round(buckets[b].base_expected) - Math.round(buckets[b].expected)
  };
});

const expectedCash = aging.reduce(function (s, b) { return s + b.expected_cash; }, 0);
const expectedCashBefore = aging.reduce(function (s, b) { return s + b.expected_cash_before_risk; }, 0);

const disputed = live.filter(function (r) { return r.outcome === 'disputed'; });
const promised = live.filter(function (r) { return r.outcome === 'promise_held'; });
const broken = live.filter(function (r) { return r.broken_promise; });
const dataProblems = invoices.filter(function (r) { return r.outcome === 'data_problem'; });

const chased = customers.filter(function (c) { return c.next_action === 'chase'; });
const heldBack = customers.filter(function (c) { return c.next_action === 'hold'; });
const invoicesCovered = sum(chased, 'invoice_count');

const pinged = customers.filter(reachesSlack);
const pingedViaEscalation = pinged.filter(function (c) { return c.route === 'escalate'; });
const pingedViaFilter = pinged.filter(function (c) { return c.route === 'reminder'; });
const flaggedButUnrouted = customers.filter(function (c) { return c.notify_manager === true && !reachesSlack(c); });

// Nothing assessed is allowed to fall below the customer grain unnamed. Every
// invoice must appear in the log either as chased or as explicitly held.
// Built from the rows the data table HANDED BACK, not from what this run
// intended to write. A guard that reads its own intentions cannot fail.
// Read via $('Write to Collection Log') and not $input, because this node is
// executeOnce and $input would hand back only the first row:
// the previous version counted the in-memory Code node values, so it would
// have reported "none lost" even against the old workflow that really did
// drop two invoices. Only a row the table returned with its own id counts.
const writtenRows = $('Write to Collection Log').all().map(function (i) { return i.json; })
  .filter(function (r) { return r && r.id !== null && r.id !== undefined; });
const namedInLog = {};
for (const r of writtenRows) {
  splitNumbers(r.invoice_numbers).forEach(function (n) { namedInLog[n] = true; });
  splitNumbers(r.held_invoice_numbers).forEach(function (n) { namedInLog[n] = true; });
}
const assessedNumbers = invoices.map(function (r) { return r.invoice_number; });
const missingFromLog = assessedNumbers.filter(function (n) { return !namedInLog[n]; });

const overdueValue = sum(live.filter(function (r) { return (Number(r.days_overdue) || 0) > 0; }), 'outstanding');
const totalOutstanding = sum(live, 'outstanding');
const weightedDaysOverdue = totalOutstanding > 0
  ? Math.round(live.reduce(function (s, r) {
      return s + (Number(r.outstanding) || 0) * Math.max(0, Number(r.days_overdue) || 0);
    }, 0) / totalOutstanding)
  : 0;

return [{
  json: {
    run_id: String($execution.id || 'manual'),
    ran_on: new Date().toISOString().slice(0, 10),
    invoices_open: live.length,
    total_outstanding: totalOutstanding,
    overdue_value: overdueValue,
    overdue_pct: totalOutstanding > 0 ? Math.round((overdueValue / totalOutstanding) * 1000) / 10 : 0,
    weighted_days_overdue: weightedDaysOverdue,
    expected_cash_30d: expectedCash,
    expected_cash_before_risk: expectedCashBefore,
    risk_discount: expectedCashBefore - expectedCash,
    risk_adjustments: adjustments.sort(function (a, b) { return b.reduction - a.reduction; }),
    risk_adjustment_count: adjustments.length,
    aging: aging,
    messages_sent: chased.length,
    invoices_covered: invoicesCovered,
    messages_saved: invoicesCovered > chased.length ? invoicesCovered - chased.length : 0,
    clerk_minutes_saved: invoicesCovered * MINUTES_PER_MANUAL_CHASE,
    customers_held: heldBack.length,
    manager_pings: pinged.length,
    manager_pings_via_escalation: pingedViaEscalation.length,
    manager_pings_via_large_balance: pingedViaFilter.length,
    manager_pinged_customers: pinged.map(function (c) {
      return { customer: c.customer_name, manager: c.account_manager_slack, outstanding: c.total_outstanding, via: c.route === 'escalate' ? 'final notice' : 'balance over threshold' };
    }),
    manager_flagged_without_route: flaggedButUnrouted.map(function (c) { return c.customer_name; }),
    invoices_assessed: assessedNumbers.length,
    invoices_named_in_log: Object.keys(namedInLog).length,
    log_rows_confirmed: writtenRows.length,
    log_rows_expected: customers.length,
    log_rows_missing: customers.length - writtenRows.length,
    invoices_missing_from_log: missingFromLog,
    log_covers_every_invoice: missingFromLog.length === 0,
    disputed_count: disputed.length,
