    outgoing: chased.map(function (c) {
      return {
        customer: c.customer_name,
        stage: c.stage,
        invoices: c.invoice_count,
        numbers: c.invoice_numbers,
        outstanding: c.total_outstanding,
        oldest_days: c.oldest_days_overdue,
        to: c.contact_email,
        manager_pinged: reachesSlack(c),
        manager: c.account_manager_slack,
        also_held: c.held_invoice_numbers
      };
    }),
    held_back: heldBack.map(function (c) {
      return {
        customer: c.customer_name,
        why: c.hold_reason,
        invoices: c.assessed_invoice_numbers,
        outstanding: c.total_outstanding
      };
    })
  }
}];

